from watcher_runtime import harness
from watcher_runtime.adapters import transit_bvg

STOP_ID = "900100003"
DEADLINE_ISO = "2026-10-01T12:00:00+00:00"

try:
    now = harness.now()
    deadline = harness.parse_time(DEADLINE_ISO)
    # If deadline has passed, worry is resolved (no cancellation seen)
    if now >= deadline:
        harness.emit(
            "resolved",
            "Morning passed; no S1 cancellation observed.",
            "bvg",
            {"cancelled": False},
            fear_came_true=False
        )
    else:
        data = transit_bvg.fetch(stop_id=STOP_ID)
        departures = data.get("departures", [])
        cancelled_found = False
        evidence = {}
        for dep in departures:
            if dep.get("line") == "S1" and dep.get("cancelled") is True:
                when_str = dep.get("when")
                if when_str:
                    when_dt = harness.parse_time(when_str)
                    if when_dt < deadline:
                        cancelled_found = True
                        evidence = {
                            "line": dep.get("line"),
                            "direction": dep.get("direction"),
                            "when": when_str,
                            "platform": dep.get("platform"),
                            "delay_s": dep.get("delay_s")
                        }
                        break
        if cancelled_found:
            harness.emit(
                "act_now",
                "S1 from Alexanderplatz is cancelled tomorrow morning.",
                "bvg",
                evidence,
                next_check_s=300
            )
        else:
            harness.emit(
                "ok",
                "No S1 cancellation found for tomorrow morning.",
                "bvg",
                next_check_s=300
            )
except Exception as e:
    harness.fail("I couldn't check the BVG departures just now.")
